// RESPONSIBILITY: Defines runtime validation schemas for profile_overview; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_profile/profile_overview/schemas/AdminProfileOverviewSchemas.ts)

// Generated by ts-to-zod
import { z } from "zod";

export const adminProfileDataSchema = z.object({
    id: z.string(),
    name: z.string(),
    email: z.string(),
    phone: z.string(),
    role: z.string(),
    branchName: z.string(),
    joinedAt: z.string(),
    avatarInitial: z.string()
});

export const updateAdminProfilePayloadSchema = z.object({
    name: z.string().trim().min(2, 'profile.validation.nameRequired').max(100, 'profile.validation.nameTooLong'),
    phone: z.string().trim().min(7, 'profile.validation.phoneInvalid').max(20, 'profile.validation.phoneInvalid').regex(/^[+0-9()\s.-]+$/, 'profile.validation.phoneInvalid')
});

export const updateAdminPasswordPayloadSchema = z.object({
    currentPassword: z.string().min(1),
    newPassword: z.string().min(8, 'profile.validation.passwordMinLength'),
    confirmPassword: z.string().min(8, 'profile.validation.passwordMinLength'),
}).refine((value) => value.newPassword === value.confirmPassword, {
    path: ['confirmPassword'],
    message: 'profile.validation.passwordMismatch',
});


export const profileTabSchema = z.union([z.literal("personal"), z.literal("security")]);

/** The supplied profile mock contract returns data: null for a successful password change. */
export const adminProfilePasswordUpdateResponseSchema = z.null();
